(function(){'use strict';function debounce(fn,delay){var timer;return function(){var ctx=this;var args=arguments;clearTimeout(timer);timer=setTimeout(function(){fn.apply(ctx,args);},delay);};}function initMobileMenu(){try{var hamburger=document.getElementById('hamburger');var nav=document.getElementById('main-nav');if(!hamburger||!nav)return;function getFocusable(){return Array.prototype.slice.call(nav.querySelectorAll('a[href],button:not([disabled]),[tabindex]:not([tabindex="-1"])'));}function openMenu(){nav.classList.add('nav-open');hamburger.setAttribute('aria-expanded','true');var focusable=getFocusable();if(focusable.length>0){focusable[0].focus();}}function closeMenu(){nav.classList.remove('nav-open');hamburger.setAttribute('aria-expanded','false');hamburger.focus();}hamburger.addEventListener('click',function(){var isOpen=hamburger.getAttribute('aria-expanded')==='true';if(isOpen){closeMenu();}else{openMenu();}});nav.addEventListener('click',function(e){if(e.target&&e.target.classList.contains('nav-link')){closeMenu();}});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&nav.classList.contains('nav-open')){closeMenu();}});nav.addEventListener('keydown',function(e){if(!nav.classList.contains('nav-open'))return;if(e.key!=='Tab')return;var focusable=getFocusable();if(focusable.length===0)return;var first=focusable[0];var last=focusable[focusable.length-1];if(e.shiftKey){if(document.activeElement===first){e.preventDefault();last.focus();}}else{if(document.activeElement===last){e.preventDefault();first.focus();}}});document.addEventListener('click',function(e){if(nav.classList.contains('nav-open')&&!nav.contains(e.target)&&!hamburger.contains(e.target)){closeMenu();}});}catch(err){console.error('[MobileMenu]Initialization failed:',err);}}function initSmoothScroll(){try{var anchorLinks=document.querySelectorAll('a[href^="#"]');Array.prototype.forEach.call(anchorLinks,function(link){link.addEventListener('click',function(e){var href=link.getAttribute('href');if(!href||href==='#')return;var target=document.querySelector(href);if(!target)return;e.preventDefault();target.scrollIntoView({behavior:'smooth',block:'start'});if(!target.hasAttribute('tabindex')){target.setAttribute('tabindex','-1');}target.focus({preventScroll:true});});});}catch(err){console.error('[SmoothScroll]Initialization failed:',err);}}function initLazyLoading(){try{if('loading' in HTMLImageElement.prototype){var nativeLazyImages=document.querySelectorAll('img[loading="lazy"]');Array.prototype.forEach.call(nativeLazyImages,function(img){if(img.complete){img.classList.add('loaded');}else{img.addEventListener('load',function(){img.classList.add('loaded');});}});return;}var lazyImages=document.querySelectorAll('img[data-src]');if(lazyImages.length===0)return;if('IntersectionObserver' in window){var observer=new IntersectionObserver(function(entries,obs){Array.prototype.forEach.call(entries,function(entry){if(!entry.isIntersecting)return;var img=entry.target;if(img.dataset.src){img.src=img.dataset.src;img.removeAttribute('data-src');img.addEventListener('load',function(){img.classList.add('loaded');});}obs.unobserve(img);});},{rootMargin:'200px 0px'});Array.prototype.forEach.call(lazyImages,function(img){observer.observe(img);});return;}Array.prototype.forEach.call(lazyImages,function(img){if(img.dataset.src){img.src=img.dataset.src;img.removeAttribute('data-src');}});}catch(err){console.error('[LazyLoad]Initialization failed:',err);}}function initActiveNavHighlighting(){try{var sections=document.querySelectorAll('section[id]');var navLinks=document.querySelectorAll('.nav-link');if(sections.length===0||navLinks.length===0)return;function setActiveLink(id){Array.prototype.forEach.call(navLinks,function(link){var href=link.getAttribute('href');if(href==='#'+id){link.classList.add('active');}else{link.classList.remove('active');}});}var observer=new IntersectionObserver(function(entries){Array.prototype.forEach.call(entries,function(entry){if(entry.isIntersecting){setActiveLink(entry.target.id);}});},{rootMargin:'-20% 0px-70% 0px',threshold:0,});Array.prototype.forEach.call(sections,function(section){observer.observe(section);});}catch(err){console.error('[ActiveNav]Initialization failed:',err);}}function initStickyHeader(){try{var header=document.querySelector('.site-header');if(!header)return;var handleScroll=debounce(function(){if(window.scrollY>10){header.classList.add('scrolled');}else{header.classList.remove('scrolled');}},50);window.addEventListener('scroll',handleScroll,{passive:true});}catch(err){console.error('[StickyHeader]Initialization failed:',err);}}function init(){initMobileMenu();initSmoothScroll();initLazyLoading();initActiveNavHighlighting();initStickyHeader();}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();